<script setup lang="ts">
import { onMounted, onUnmounted, ref } from 'vue';
import { api, USER_ID } from '@/api/client';
import { useSessionStore } from '@/stores/session';
import ReviewReader from './ReviewReader.vue';
import ReviewLatexEditor from './ReviewLatexEditor.vue';
type Usage={steps:number;inputTokens:number;outputTokens:number;cacheReadTokens:number;cacheWriteTokens:number;providerEstimatedCostUsd:number|null};
type Topic={fullText?:{phase:string;lanes?:{fullText:{phase:string}}[];lastError?:string;papers?:{sourceId:string;status:string}[]};paperFigures?:{phase:string;lastError?:string;figureCount?:number;gaps?:string[]};completionRecovery?:{status:string;nextAttemptAt:string;stage:string};validationIssues?:{sourceId:string;field:string;actual:string;expected:string}[];lastRepairVerification?:{result:string};researchReady?:boolean;progressLabel?:string;needsUserAction?:boolean;blockingReasons?:string[];id:string;title:string;status:string;projectId:string;dependsOn:string[];error?:string;sourceCount?:number;draftUsage?:Usage;auditUsage?:Usage;retryCount?:number;retryLimit?:number;availableArtifacts?:string[];availableAuditArtifacts?:string[];deliveryState?:string;formatRecovery?:unknown;recoveryStage?:string;illustrated?:boolean;figureCount?:number;figureUsage?:Usage;availableFigureArtifacts?:string[]};
type Campaign={id:string;status:string;paused?:boolean;error?:string;topics:Topic[];maxConcurrentCampaigns?:number;continuousCompletion?:boolean;automaticRuntimeRecovery?:boolean;automaticRevision?:boolean};
const fulltextLabels:Record<string,string>={discovery_pending:"等待文献发现",discovering:"检索原论文",plan_pending:"等待全文定位",planning:"定位各篇全文",fetching:"下载与提取完整 PDF",reading:"逐段阅读全文及实际页面图",work_pending:"准备下一篇",waiting:"处理全文缺口/运行故障",ready:"全文及页面阅读记录齐备"};
const session=useSessionStore();
const latex=ref<{campaign:Campaign;topic:Topic}|null>(null);
const reader=ref<{campaign:Campaign;topic:Topic;view?:'text'|'figures'}|null>(null);
const artifactLabels:Record<string,string>={'review.md':'Markdown 源文（纯文本）','sources.json':'来源清单','evidence.csv':'证据表','protocol.md':'检索协议','gaps.md':'不足与待核问题','audit.md':'审查报告','audit.json':'审查记录'};
function artifactUrl(c:Campaign,t:Topic,name:string){return `/api/reviews/${encodeURIComponent(c.id)}/topics/${encodeURIComponent(t.id)}/artifacts/${encodeURIComponent(name)}?userId=${encodeURIComponent(USER_ID)}`;}
const now=ref(Date.now());
function recoveryLabel(t:Topic){const r=t.completionRecovery;if(!['blocked','needs_revision'].includes(t.status)||r?.status!=='waiting')return '';const seconds=Math.max(0,Math.ceil((Date.parse(r.nextAttemptAt)-now.value)/1000));return `自动接续${seconds?'倒计时 '+Math.ceil(seconds/60)+' 分钟':'即将派发'} · ${r.stage==='audit'?'只恢复审查':r.stage==='figures'?'继续制图':'定向修订'}，保留已有稿件`;}
const batches=ref<Campaign[]>([]), error=ref(''), busy=ref(false);
const paperLabels:Record<string,string>={waiting_base:'等待成稿通过核查',plan_pending:'等待寻找原论文',planning:'查找原论文PDF',fetch_pending:'等待下载全文',fetching:'下载全文与逐页预览',select_pending:'等待选取原图',selecting:'核对图号与选择裁剪区域',render_pending:'等待原图排版',rendering:'裁剪原图并组合排版',check_pending:'等待独立核对原图',checking:'核对原图、裁剪与插入位置',assemble_pending:'等待生成补图版',assembling:'生成补图版，保留原稿',ready:'原图补充版已就绪',no_sources:'本轮没有可核实的适用原图',waiting:'保留原稿，等待补图阶段恢复'};
const labels:Record<string,string>={queued:'等待拆分',planning:'正在拆分课题',running:'推进中',pending:'等待前置任务或执行席位',drafting:'检索与撰写',illustration_pending:'等待综述制图',illustrating:'绘制综述图',audit_pending:'等待图文与证据核查',auditing:'核查来源与论断',draft_ready:'草稿及模型审查已就绪',needs_attention:'有课题需要处理',needs_revision:'需要修订',blocked:'受阻'};
let timer:ReturnType<typeof setInterval>|undefined;
let loading=false;
function usage(u:Usage){return `${u.steps} 步 · 新输入 ${u.inputTokens} / 输出 ${u.outputTokens} token · 缓存读 ${u.cacheReadTokens} / 写 ${u.cacheWriteTokens} · ${u.providerEstimatedCostUsd==null?'费用未知':`提供商估算 $${u.providerEstimatedCostUsd.toFixed(4)}（非账单）`}`;}
async function load(){now.value=Date.now();if(loading)return;loading=true;try{batches.value=(await api.get('/api/reviews',{params:{userId:USER_ID}})).data;error.value='';}catch(e){error.value=e instanceof Error?e.message:'综述队列读取失败';}finally{loading=false;}}
async function pause(c:Campaign){busy.value=true;try{await api.post(`/api/reviews/${c.id}/pause`,{userId:USER_ID,paused:!c.paused});await load();}catch(e){error.value=String(e);}finally{busy.value=false;}}
onMounted(()=>{void load();timer=setInterval(load,10000);});onUnmounted(()=>clearInterval(timer));
</script>
<template>
  <section v-if="batches.length || error" class="review-queue" aria-label="综述任务队列">
    <p v-if="error" role="alert">{{ error }}</p>
    <details v-for="c in batches" :key="c.id" :open="c.status!=='voided'">
      <summary>综述计划 · {{ c.status==='voided' ? '旧成果已作废 · 仅历史留存' : c.paused ? '已暂停后续步骤' : labels[c.status] || c.status }}</summary>
      <p class="policy">最多 {{ c.maxConcurrentCampaigns ?? 1 }} 批综述并行 · 同批次依次推进 · 低价模型，无 GPU · 中文写作 → 制图 → 图文与证据核查。暂停本批次不影响其他批次。模型通过不等于专家验收。</p>
      <p v-if="c.continuousCompletion" class="policy">持续完成已开启：受阻后自动诊断、定向修复、切换已允许的低价模型并复核。重复失败逐步延长等待，保留材料与记录；旧单步恢复次数不再终止课题。可随时暂停本批次。</p><p v-if="c.automaticRuntimeRecovery && !c.continuousCompletion" class="policy">暂时性运行故障自动等待并从失败阶段恢复，最多两次；证书故障最多一次，始终保留证书校验与已有材料。</p><p v-if="c.automaticRevision && !c.continuousCompletion" class="policy">审查退修会在剩余次数内自动处理并复核；达到上限才需要处理。</p><p v-if="c.error" role="alert">{{ c.error }}</p>
      <ol><li v-for="t in c.topics" :key="t.id"><button class="topic" @click="session.focusTask(t.projectId)">{{ t.title }}</button><small>{{ recoveryLabel(t) || (t.progressLabel?.startsWith('自动修订中') ? '自动修订中 · ' + (labels[t.status] || t.status) : t.progressLabel || labels[t.status] || t.status) }}<template v-if="t.sourceCount"> · {{ t.sourceCount }} 条来源</template></small><small v-if="t.fullText">全文阶段 · {{fulltextLabels[t.fullText.phase] || t.fullText.phase}} · 已读 {{t.fullText.papers?.filter(p=>p.status==='read').length ?? 0}} / {{t.fullText.papers?.filter(p=>p.status!=='reference_only').length ?? 0}} 篇论文 · {{t.fullText.lanes?.filter(l=>['fetching','reading'].includes(l.fullText.phase)).length ?? 0}} 篇并行处理</small><small v-if="t.fullText?.lastError">{{t.fullText.lastError}}</small><small v-if="t.retryCount">故障恢复 / 修订：{{ t.retryCount }} / {{ t.retryLimit ?? 2 }} 次（流程上限，非账户余额）</small><small v-if="t.dependsOn.length">前置：{{ t.dependsOn.map(id=>c.topics.find(x=>x.id===id)?.title || id).join('；') }}</small><small v-if="t.researchReady">已有独立核查事实可供后续任务复用；图文交付仍单独验收</small><small v-if="t.deliveryState">{{ t.deliveryState }}</small><small v-if="t.formatRecovery">来源格式已无损恢复；原文件和修复记录保留</small><small v-if="t.recoveryStage === 'audit' && ['audit_pending','auditing','blocked'].includes(t.status)">本次仅恢复独立审查，沿用原稿</small><small v-if="t.paperFigures">论文原图补充 · {{paperLabels[t.paperFigures.phase] || t.paperFigures.phase}}<template v-if="t.paperFigures.figureCount"> · 新增{{t.paperFigures.figureCount}}幅</template></small><small v-if="t.paperFigures?.lastError && t.paperFigures.phase==='waiting'">{{t.paperFigures.lastError}}</small><small v-for="gap in t.paperFigures?.gaps ?? []" :key="gap">原图缺口：{{gap}}</small><small v-if="t.illustrated">图文交付 · {{ t.figureCount ?? 0 }} 幅已渲染图</small><div class="artifact-links"><button @click="latex={campaign:c,topic:t}">LaTeX 工作台</button><button v-if="t.availableArtifacts?.includes('review.md')" @click="reader={campaign:c,topic:t}">打开图文阅读稿</button><button v-if="t.figureCount" @click="reader={campaign:c,topic:t,view:'figures'}">查看图片（{{t.figureCount}}）</button><a v-for="name in [...(t.availableArtifacts ?? []), ...(t.availableAuditArtifacts ?? [])]" :key="name" :href="artifactUrl(c,t,name)" target="_blank" rel="noopener">{{ artifactLabels[name] || name }}</a></div><small v-if="t.draftUsage">调研：{{ usage(t.draftUsage) }}</small><small v-if="t.figureUsage">制图：{{ usage(t.figureUsage) }}</small><small v-if="t.auditUsage">核查：{{ usage(t.auditUsage) }}</small><small v-if="t.needsUserAction" class="error">需要处理：{{ (t.retryCount ?? 0) >= (t.retryLimit ?? 2) ? '已达到本课题恢复次数上限' : '请查看执行错误或审查原因' }}</small><small v-for="reason in t.blockingReasons ?? []" :key="reason">审查原因：{{ reason }}</small><small v-for="issue in t.validationIssues ?? []" :key="issue.sourceId+issue.field" class="error">来源 {{ issue.sourceId }} · {{ issue.field }}：{{ issue.actual }}；要求：{{ issue.expected }}</small><small v-if="t.lastRepairVerification?.result === 'source-check-passed'">上一轮来源字段问题已通过重新校验；仍须后续科学审查</small><small v-if="t.error" class="error">{{ t.error }}</small></li></ol>
      <button v-if="['queued','planning','running'].includes(c.status)" :disabled="busy" @click="pause(c)">{{ c.paused ? '继续后续步骤' : '暂停后续步骤' }}</button>
      <small v-if="c.paused">正在执行的步骤会保留并运行至结束；之后不再派发。</small>
    </details>
  </section>
  <ReviewLatexEditor v-if="latex" :campaign-id="latex.campaign.id" :topic-id="latex.topic.id" :project-id="latex.topic.projectId" :title="latex.topic.title" @close="latex=null" />
  <ReviewReader v-if="reader" :campaign-id="reader.campaign.id" :topic-id="reader.topic.id" :title="reader.topic.title" :status="reader.topic.status" :initial-view="reader.view" @close="reader=null" />
</template>
<style scoped>
.artifact-links{display:flex;flex-wrap:wrap;gap:6px 12px;margin:4px 0}.artifact-links a{color:var(--color-brain)}.review-queue{padding:10px 14px;max-height:260px;overflow:auto;border-bottom:1px solid color-mix(in srgb,var(--color-ink) 12%,transparent);font-size:12px;flex-shrink:0}.policy,small{color:var(--color-ink-soft);line-height:1.5}small{display:block}summary,button{cursor:pointer}ol{padding-left:20px}li{margin:8px 0}button{font:inherit;border:1px solid color-mix(in srgb,var(--color-ink) 15%,transparent);background:var(--color-elev);color:var(--color-ink);padding:6px;border-radius:6px}.topic{text-align:left;border:0;padding:0;background:none}.error{color:var(--color-danger,#b74b38)}button:focus-visible,summary:focus-visible{outline:2px solid var(--color-brain)}
</style>
